import{_ as i,o as a,c as l,ag as t}from"./chunks/framework.D9ghT4bC.js";const v=JSON.parse('{"title":"UncivCN 更新日志","description":"","frontmatter":{"title":"UncivCN 更新日志"},"headers":[],"relativePath":"zh/UncivCN/Changelog.md","filePath":"zh/UncivCN/Changelog.md"}'),o={name:"zh/UncivCN/Changelog.md"};function r(d,e,n,u,c,h){return a(),l("div",null,[...e[0]||(e[0]=[t('<h1 id="uncivcn-更新日志" tabindex="-1">UncivCN 更新日志 <a class="header-anchor" href="#uncivcn-更新日志" aria-label="Permalink to &quot;UncivCN 更新日志&quot;">​</a></h1><p>版本号规则：上游版本 + CN 子版本号（<code>.1</code>、<code>.2</code>、<code>.3</code>…，同一上游版本可发多个 CN 子版本，如 4.20.8.1 → 4.20.8.4；跟进新上游后从 <code>.1</code> 重新开始，如 4.21.5 → 4.21.5.1）。</p><p>详细历史记录见 <a href="/Unciv/zh/UncivCN/Changelog.html">UncivCN 更新日志（社区归档）</a>。</p><h2 id="未发布-unreleased" tabindex="-1">未发布（Unreleased） <a class="header-anchor" href="#未发布-unreleased" aria-label="Permalink to &quot;未发布（Unreleased）&quot;">​</a></h2><ul><li>CI：GitHub Release 标题改为显式使用纯版本号（如 4.21.6.4），不再使用上传动作自动填充的冗长名称</li></ul><h2 id="v4-21-6-4-build-1248" tabindex="-1">v4.21.6.4（build 1248） <a class="header-anchor" href="#v4-21-6-4-build-1248" aria-label="Permalink to &quot;v4.21.6.4（build 1248）&quot;">​</a></h2><ul><li>CI：修复 GitHub Release 说明文本为空——现在按发布 tag 从 CN 中英文更新日志（docs/UncivCN + docs/zh/UncivCN）提取对应版本小节，中英双语写入 Release 说明（此前 CN 四段式版本号在上游 changelog.md 中不存在，导致正文为空）</li><li>模组管理：新增“模组下载源”设置（选项 → 高级），国内等无法稳定访问 GitHub 的玩家可将模组列表、预览图与下载全部切到公共 GitHub 加速镜像（gh-proxy.com / ghfast.top / ghproxy.net，或任意自定义前缀）；官方源加载模组列表失败时，游戏会弹窗询问一键切换镜像源并自动重试；新增“国内玩家模组安装指南”文档页</li><li>移除新建游戏页&quot;重置为默认&quot;按钮：读取配置列表新增内置且不可删除的&quot;默认配置&quot;条目，可恢复完全相同的默认选项（保留原确认弹窗）</li><li>新建游戏页新增&quot;保存当前配置/读取已保存配置&quot;按钮（位于剪贴板按钮右侧）：配置以与剪贴板导出相同的格式存入 SaveFiles/GameSetup 下的命名槽位，读取弹窗可选择或删除槽位；窄屏时按钮独占一行，位于剪贴板行与开始游戏行之间</li><li>新建游戏页的剪贴板复制/粘贴按钮从左上角（游戏选项列顶部）移到右下角&quot;开始游戏&quot;旁：宽屏与开始游戏同一行、位于其左侧；窄屏单独一行放在开始游戏上方，避免撑破底部栏</li><li>文档：Coding-standards 新增发版检查清单与踩坑经验（tag 推送、文档站本地验证、禁止裸尖括号、Maven Central 403、Unciv.jar 旧名残留、continue-on-error 掩盖失败、CN 词条翻译完整性）</li></ul><h2 id="v4-21-6-3-build-1247" tabindex="-1">v4.21.6.3（build 1247） <a class="header-anchor" href="#v4-21-6-3-build-1247" aria-label="Permalink to &quot;v4.21.6.3（build 1247）&quot;">​</a></h2><ul><li>修复 Docker 构建：Dockerfile 复制的 <code>Unciv.jar</code> 在 CN 分支实际产物名为 <code>UncivCN.jar</code>（改名后镜像构建一直失败）</li><li>修复 MSI 发布：<code>wix build</code> 默认按源文件名输出 <code>unciv.msi</code>，而上传路径是 <code>UncivCN.msi</code>；<code>build-msi</code> job 带 <code>continue-on-error: true</code>，历次 Release 从未包含 MSI——现在显式指定输出文件名</li></ul><h2 id="v4-21-6-2-build-1246" tabindex="-1">v4.21.6.2（build 1246） <a class="header-anchor" href="#v4-21-6-2-build-1246" aria-label="Permalink to &quot;v4.21.6.2（build 1246）&quot;">​</a></h2><ul><li>修复 CN 自研功能词条缺失简体中文翻译（47 个缺失 + 10 个空翻译）：剪贴板复制/粘贴游戏设置、轮询联机（轮询间隔、刷新、在线玩家、回合计时）、镜像地图对称模式、自动锁定、地图钉笔记、读档随机数变动、Countables、寒带/螺旋地图类型等——此前显示为英文</li></ul><h2 id="v4-21-6-1-build-1245" tabindex="-1">v4.21.6.1（build 1245） <a class="header-anchor" href="#v4-21-6-1-build-1245" aria-label="Permalink to &quot;v4.21.6.1（build 1245）&quot;">​</a></h2><ul><li>修复笔记跨存档泄漏：笔记改为按 gameId 存储（&quot;notes_{gameId}&quot;）而非存档文件名——同一局游戏的手动存档/自动存档/另存为共享笔记，不同游戏严格隔离（此前共享的 &quot;Autosave&quot; 名称会导致笔记在不同游戏的自动存档间串档，且未保存的新游戏笔记会丢失）；旧 &quot;{存档名}_notes&quot; 文件首次加载时自动迁移，删档时两种命名都会清理，存档列表过滤新命名</li><li>地图钉/单位钉交互重构：手机长按、桌面 Alt+点击即可编辑备注，无需任何开关（普通点击永不被劫持，旧开关保留为备选）；备注气泡截断为 8 字符，点击气泡弹出全文查看（支持编辑/删除）；地块笔记开关改用星标图标，两个开关桌面悬停有文字提示</li><li>修复地图钉/单位钉窗口本地化：补齐笔记相关 UI 词条的中文翻译（&quot;为地块添加笔记&quot;、&quot;为[unitName]添加笔记&quot;、&quot;添加笔记&quot;、&quot;笔记&quot;、&quot;显示单位/地块笔记&quot;）——此前显示为英文</li><li>修复打开地图钉编辑弹窗时崩溃：地块材质包预览使用的 TileMapView 按地块数分配数组，真实地块（非零索引）会越界（现按最大索引扩容，并新增回归测试）</li><li>地图钉编辑弹窗：标题去掉地块坐标，左侧占位图标改为选中地块的材质包实时预览（地形/资源/改良/河流贴图）</li><li>内置基础规则集（Vanilla / Gods &amp; Kings）与上游对齐：移除 G&amp;K ModOptions 中 CN 独有的 &quot;Allow cities to claim tiles&quot;（tile-claim 改为模组通过 ModOptions 自行声明启用）与 CN 独有的大军事家 8 回合黄金时代 unique（上游 #13308 已移除）</li><li>修复开图界面：世界大小设为自定义后反复切换对称性会堆积重复的半径/宽度/高度输入行（六边形/矩形尺寸表重建时未清空）</li><li>新特性：<code>ModOptions.json</code> 模组版本要求——<code>modVersion</code>（n.n.n，不填默认 0.0.1）、<code>gameVersionRange</code>（min~max，不填默认全版本可用）、<code>modDependencies</code>（精确或范围版本要求）；不满足时在模组管理器、新建游戏模组选择与模组检查器中显示警告，不阻止使用</li><li>修复文档站死链接：中文 UncivCN 页面 14 处 <code>](</code> 损坏链接，以及 Modders 文档（中英，含 <code>UniqueType.kt</code> / <code>Countables.kt</code> / <code>UniqueDocsWriter</code> / <code>MergeActionDocsWriter</code> 生成器）约 250 处标题锚点错误（VitePress slug 格式）；已用全新 VitePress 构建产物逐链接验证</li><li>合并上游 4.21.6：CPU 性能优化（城市基线只算一次，部分存档下一回合提速约 20%）、AI 工人考虑未来的相邻加成、多人上传失败视觉提示、聊天昵称显示文明颜色、OneTimeGainStat 参数改为 <code>[civWideStat]</code> 并对非文明级产出给出 modding 警告、测试运行器重构（详见上游 <a href="https://github.com/AutumnPizazz/Unciv/blob/UncivCN/changelog.md" target="_blank" rel="noreferrer">changelog.md</a>）</li><li>修复自定义域名下文档站无样式：站点产物部署到 <code>Unciv/</code> 子目录并加根跳转页</li><li>修复导航栏 logo 路径重复 <code>/Unciv</code> 前缀</li><li>游戏内版本号改为构建时自动从 <code>BuildConfig.kt</code> 同步到 <code>UncivGame.kt</code>（此前手动发版容易漏同步，导致游戏内显示的版本号滞后）</li><li><code>AGENTS.md</code> 瘦身为纯行为规则；构建命令、项目结构、游戏状态模型、资源路径等开发参考移入 Coding-standards，该文档升级为工程手册（中英同步）</li><li>新增合并上游规范：自行解决与母仓库 master 的合并冲突并完整接入新特性；双方实现方式冲突时先向用户提问定夺</li></ul><h2 id="v4-21-5-3-build-1244" tabindex="-1">v4.21.5.3（build 1244） <a class="header-anchor" href="#v4-21-5-3-build-1244" aria-label="Permalink to &quot;v4.21.5.3（build 1244）&quot;">​</a></h2><ul><li>修复 CI 测试失败：13 行翻译模板缺末尾空格（TranslationTests 挂掉）；测试模组 testMOD / testMapScript 此前被 .gitignore 忽略，导致 CI 上 Lua 脚本与合并动作测试大量失败，现已纳入版本库并补充 testMOD/jsons/Buildings.json</li><li>Deploy 工作流不再向 Discord 推送发布通知（GitHub Release 上传保留）</li></ul><h2 id="v4-21-5-2-build-1243" tabindex="-1">v4.21.5.2（build 1243） <a class="header-anchor" href="#v4-21-5-2-build-1243" aria-label="Permalink to &quot;v4.21.5.2（build 1243）&quot;">​</a></h2><ul><li>官方文档站上线：全新 VitePress 文档站（替换 mkdocs），支持中文全文搜索、中英文一键切换、unique 列表一键复制 <ul><li>英文区完整复用上游文档；中文区为完整翻译镜像（Modders / Developers / Translating / Other 等全部页面）</li><li>新增 UncivCN 专区（分支介绍 / 新特性 / 更新日志 / 差异对照 / 代码规范 / 轮询联机）与社区内容区（原版攻略 / 模组专区 / 源码分析 / 上游更新日志），均提供中英双语</li></ul></li><li>unique 说明文档中文化：新增 docDescriptionZh 机制，模组制作者可在文档站查看中文 unique 说明</li><li>构建与发布流程适配：APK 签名本地化（zipalign + apksigner V3）、产物命名 UncivCN；新增签名回归 CI</li></ul><h2 id="v4-21-5-1-build-1242" tabindex="-1">v4.21.5.1（build 1242） <a class="header-anchor" href="#v4-21-5-1-build-1242" aria-label="Permalink to &quot;v4.21.5.1（build 1242）&quot;">​</a></h2><ul><li>合并上游 4.21.5（AI 金币/战争逻辑修复、CPU 性能优化、城市邦开局优化等，详见上游 <a href="https://github.com/AutumnPizazz/Unciv/blob/UncivCN/changelog.md" target="_blank" rel="noreferrer">changelog.md</a>）</li><li>撤销自带 UCCC 模组改动，游戏本体不再打包任何模组</li><li>新增新建游戏设置导出/导入剪贴板功能</li><li>调整人口锁地按钮逻辑</li><li>修复统计显示级联 bug，与上游 master 对齐</li></ul><h2 id="v4-21-0-2-2026-8-1" tabindex="-1">v4.21.0.2（2026.8.1） <a class="header-anchor" href="#v4-21-0-2-2026-8-1" aria-label="Permalink to &quot;v4.21.0.2（2026.8.1）&quot;">​</a></h2><ul><li>修复 UCCC 模组部分 bug</li></ul><h2 id="v4-21-0-1-2026-8-1" tabindex="-1">v4.21.0.1（2026.8.1） <a class="header-anchor" href="#v4-21-0-1-2026-8-1" aria-label="Permalink to &quot;v4.21.0.1（2026.8.1）&quot;">​</a></h2><ul><li>跟进 Unciv 原版近期更新（含对称/镜像地图、统计面板等上游合入功能）</li><li>由于与上游对胜利面板均作类似功能改动，回退「禁用文明积分面板时同步禁用实验性统计面板」功能，以上游为准</li><li>补全缺失的中文本地化</li><li>联机默认服务器改为 <code>http://sp.unciv.cn:30123</code></li><li>新增人口自动锁定快捷按钮（城市屏幕右下角「自动锁定」，永久切换不锁/锁人口）</li><li>自带 UCCC 模组</li><li>随机数可通过读档改变功能联机时不再可用</li></ul><h2 id="v4-20-17-2-2026-7-12" tabindex="-1">v4.20.17.2（2026.7.12） <a class="header-anchor" href="#v4-20-17-2-2026-7-12" aria-label="Permalink to &quot;v4.20.17.2（2026.7.12）&quot;">​</a></h2><ul><li>新增单位钉、地图钉功能（详见 <a href="./Features.html#单位钉-地图钉-4-20-17-2">新特性</a>）</li><li>取消旋转对称地图对半径的奇偶限制</li><li>禁用文明积分面板时同步禁用实验性统计面板</li><li>实现游戏版本兼容性隔离（旧版无法加载新版存档）</li><li>训练移民等食物→产能单位时避免市民饿死</li></ul><h2 id="v4-20-17-1-2026-7-4" tabindex="-1">v4.20.17.1（2026.7.4） <a class="header-anchor" href="#v4-20-17-1-2026-7-4" aria-label="Permalink to &quot;v4.20.17.1（2026.7.4）&quot;">​</a></h2><ul><li>跟进 Unciv 原版一个多月的更新</li></ul><h2 id="v4-20-8-4-2026-5-26" tabindex="-1">v4.20.8.4（2026.5.26） <a class="header-anchor" href="#v4-20-8-4-2026-5-26" aria-label="Permalink to &quot;v4.20.8.4（2026.5.26）&quot;">​</a></h2><ul><li>原生模组检查器可筛查模组的 Lua 错误</li><li>轮询联机功能可查看其他玩家的在线状态</li></ul><h2 id="v4-20-8-3-2026-5-23" tabindex="-1">v4.20.8.3（2026.5.23） <a class="header-anchor" href="#v4-20-8-3-2026-5-23" aria-label="Permalink to &quot;v4.20.8.3（2026.5.23）&quot;">​</a></h2><ul><li>增强 Lua 系统</li><li>event 可挂载 Lua</li></ul><h2 id="v4-20-8-2-2026-5-22" tabindex="-1">v4.20.8.2（2026.5.22） <a class="header-anchor" href="#v4-20-8-2-2026-5-22" aria-label="Permalink to &quot;v4.20.8.2（2026.5.22）&quot;">​</a></h2><ul><li>模组支持 <a href="/Unciv/zh/Modders/Lua-Modding.html">Lua 脚本</a></li><li>修复「众神与国王」精英教育政策不送伟人的 bug</li><li>Amount 参数兼容 Countables，新增多个 Countables 参数类型</li><li>修复 TRY_INJECT 单位时将造价覆盖为 0 的 bug</li></ul><h2 id="v4-20-8-1-2026-5-21" tabindex="-1">v4.20.8.1（2026.5.21） <a class="header-anchor" href="#v4-20-8-1-2026-5-21" aria-label="Permalink to &quot;v4.20.8.1（2026.5.21）&quot;">​</a></h2><ul><li>重磅更新！新增 <a href="./Polling-multiplayer.html">轮询联机功能</a></li></ul><h2 id="v4-20-7-4-2026-5-19" tabindex="-1">v4.20.7.4（2026.5.19） <a class="header-anchor" href="#v4-20-7-4-2026-5-19" aria-label="Permalink to &quot;v4.20.7.4（2026.5.19）&quot;">​</a></h2><ul><li>中心对称地图现在让资源数量也对称分布</li></ul><h2 id="v4-20-7-3-2026-5-19" tabindex="-1">v4.20.7.3（2026.5.19） <a class="header-anchor" href="#v4-20-7-3-2026-5-19" aria-label="Permalink to &quot;v4.20.7.3（2026.5.19）&quot;">​</a></h2><ul><li>扩展模组 JSON 系统，详见 <a href="/Unciv/zh/Modders/Mod-file-structure/6-MergeActions.html">MergeAction 教程</a></li></ul><hr><h2 id="v4-20-7-2" tabindex="-1">v4.20.7.2 <a class="header-anchor" href="#v4-20-7-2" aria-label="Permalink to &quot;v4.20.7.2&quot;">​</a></h2><p><strong>发布日期</strong>：2026.5.19</p><ul><li>安卓端安装包不再自带模组 CoeHarMod/和合共生</li><li>新增三种镜像地图模式，按两瓣/三瓣/六瓣中心对称分布</li></ul><h2 id="v4-20-6-3" tabindex="-1">v4.20.6.3 <a class="header-anchor" href="#v4-20-6-3" aria-label="Permalink to &quot;v4.20.6.3&quot;">​</a></h2><p><strong>发布日期</strong>：2026.5.17</p><ul><li>新增模组特性：</li></ul><table tabindex="0"><thead><tr><th>英文原文</th><th>中文释义</th></tr></thead><tbody><tr><td><code>Hidden from city screen</code></td><td>不再显示在城市面板中</td></tr><tr><td><code>Can be built [amount] times in each city</code></td><td>可以在单个城市中重复建造[amount]次</td></tr></tbody></table><h2 id="v4-20-6-1" tabindex="-1">v4.20.6.1 <a class="header-anchor" href="#v4-20-6-1" aria-label="Permalink to &quot;v4.20.6.1&quot;">​</a></h2><p><strong>发布日期</strong>：2026.5.16</p><ul><li>同步两个月来 Unciv 原版的更新内容</li><li>将前几个版本对随机性结果可变性的改动收束到设置页面，可选择是否启用</li></ul><h2 id="v4-19-16-2" tabindex="-1">v4.19.16.2 <a class="header-anchor" href="#v4-19-16-2" aria-label="Permalink to &quot;v4.19.16.2&quot;">​</a></h2><p><strong>发布日期</strong>：2026.3.2</p><ul><li>远古遗迹产出随机性结果可以通过读档重载改变</li></ul><h2 id="v4-19-16-1" tabindex="-1">v4.19.16.1 <a class="header-anchor" href="#v4-19-16-1" aria-label="Permalink to &quot;v4.19.16.1&quot;">​</a></h2><p><strong>发布日期</strong>：2026.3.1</p><ul><li>城邦任务随机性结果可以通过读档重载改变</li></ul><h2 id="v4-19-15-cn2" tabindex="-1">v4.19.15-cn2 <a class="header-anchor" href="#v4-19-15-cn2" aria-label="Permalink to &quot;v4.19.15-cn2&quot;">​</a></h2><p><strong>发布日期</strong>：2026.2.28</p><ul><li>新增模组特性：</li></ul><table tabindex="0"><thead><tr><th>英文原文</th><th>中文释义</th></tr></thead><tbody><tr><td><code>Attacks also target [mapUnitFilter] units within [positiveAmount] tiles</code></td><td>攻击也会同时攻击 [positiveAmount] 格内满足 [mapUnitFilter] 的单位</td></tr><tr><td><code>Attacks also target [mapUnitFilter] units within [positiveAmount] tiles, with damage decreasing by distance</code></td><td>攻击也会同时攻击 [positiveAmount] 格内满足 [mapUnitFilter] 的单位，伤害随距离递减</td></tr><tr><td><code>Takes [relativeAmount]% damage from own area attacks</code></td><td>受到自身范围攻击时，仅承受 [relativeAmount]% 的伤害</td></tr><tr><td><code>Takes [relativeAmount]% counter damage from each unit hit by its area attacks</code></td><td>其范围攻击每击中一个单位，自身就会承受该单位 [relativeAmount]% 的反击伤害</td></tr></tbody></table><ul><li>添加统计面板数据导出为 csv 表格的功能</li></ul><h2 id="v4-19-15" tabindex="-1">v4.19.15 <a class="header-anchor" href="#v4-19-15" aria-label="Permalink to &quot;v4.19.15&quot;">​</a></h2><p><strong>发布日期</strong>：2026.2.26</p><ul><li>为安卓端安装包加入内置模组 <a href="https://github.com/AutumnPizazz/CoeHarMod" target="_blank" rel="noreferrer">CoeHarMod/和合共生</a></li><li>允许相邻城市切换地块，需要在模组的 ModOptions.json 文件中声明 uniques &quot;Allow cities to claim tiles&quot;</li></ul>',64)])])}const b=i(o,[["render",r]]);export{v as __pageData,b as default};
